// Version A
class LineItem {
  product: Product;
  quantity: number;
  total() { return this.product.price * this.quantity - this.product.discountForQuantity(this.quantity); }
}
class OrderA {
  lineItems: LineItem[];
  total() { return this.lineItems.reduce((s, i) => s + i.total(), 0); }
}

// Version B
class Product { price: number; discountForQuantity(q: number) { return 0; } }
class LineItemB { product: Product; quantity: number; }
class OrderB {
  lineItems: LineItemB[];
  total() { return this.lineItems.reduce((s, li) => s + li.quantity * li.product.price - li.product.discountForQuantity(li.quantity), 0); }
}
